"""dist/json/tokens.<theme>.json: resolved tokens, one flat map per theme.

A neutral feed for consumers we don't generate code for (scripts, other build tools).
"""
from __future__ import annotations

import json
from pathlib import Path


def build(ctx, out: Path) -> list[Path]:
    out.mkdir(parents=True, exist_ok=True)
    written = []
    for theme, toks in ctx.themes.items():
        data = {
            "$schema-note": "Resolved Phosphor95 tokens. Generated by tools/build.py; do not edit.",
            "theme": theme,
            "tokens": {
                p: {"type": t.type, "value": t.value, **({"aliasOf": t.alias_of} if t.alias_of else {})}
                for p, t in sorted(toks.items())
            },
        }
        f = out / f"tokens.{theme}.json"
        f.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")
        written.append(f)
    return written
